public class LanternCounter {
    private volatile boolean asleep = false;

    public void tryToSleep() {
        while (!asleep) {
            countSomeSheep();
        }
    }

    private void countSomeSheep() {
        // Represent the action of tallying lanterns.
        System.out.println("Tallying lanterns...");
        try {
            Thread.sleep(1000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public static void main(String[] args) {
        LanternCounter counter = new LanternCounter();

        // Creating a fixed thread pool with 2 threads.
        java.util.concurrent.ExecutorService executor = java.util.concurrent.Executors.newFixedThreadPool(2);

        // Submitting tasks to the thread pool for counting lanterns and checking sleep status.
        executor.submit(() -> {
            counter.tryToSleep();
        });

        executor.submit(() -> {
            try {
                Thread.sleep(5000);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            System.out.println("Traveler is now asleep.");
            counter.asleep = true;
        });

        // Shutting down the thread pool after all tasks are completed.
        executor.shutdown();
    }
}

