import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;

class DelegatingRobotTracker {
    private final ConcurrentMap<String, int[]> robotCoordinates;

    public DelegatingRobotTracker(ConcurrentMap<String, int[]> robotCoordinates) {
        this.robotCoordinates = new ConcurrentHashMap<>(robotCoordinates);
    }

    // Retrieve the coordinates of a specific robot
    public int[] getCoordinates(String robotId) {
        return robotCoordinates.get(robotId).clone();
    }

    // Modify the coordinates of a robot if it exists in the map
    public boolean modifyCoordinates(String robotId, int[] newCoordinates) {
        return robotCoordinates.computeIfPresent(robotId, (key, value) -> {
            System.arraycopy(newCoordinates, 0, value, 0, newCoordinates.length);
            return value;
        }) != null;
    }

    // Return a live unmodifiable map backed by the original data
    public Map<String, int[]> getAllLiveCoordinates() {
        return Collections.unmodifiableMap(robotCoordinates);
    }

    // Return a static snapshot of the current state as an unmodifiable map
    public Map<String, int[]> getAllStaticCoordinates() {
        return robotCoordinates.entrySet().stream()
                .collect(Collectors.toMap(
                        Map.Entry::getKey,
                        e -> Arrays.copyOf(e.getValue(), e.getValue().length)));
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        ConcurrentHashMap<String, int[]> initialCoordinates = new ConcurrentHashMap<>();
        initialCoordinates.put("R1", new int[]{0, 0});
        initialCoordinates.put("R2", new int[]{1, 1});

        DelegatingRobotTracker tracker = new DelegatingRobotTracker(initialCoordinates);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> {
            System.out.println("Modifying coordinates for R1");
            tracker.modifyCoordinates("R1", new int[]{2, 2});
            System.out.println("R1 coordinates after modification: " + Arrays.toString(tracker.getCoordinates("R1")));
