            System.out.println("Retrieving all live coordinates");
            Map<String, int[]> liveCoords = tracker.getAllLiveCoordinates();
            System.out.println("All live coordinates: " + liveCoords);
        });

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);
    }
}

