import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;
import java.time.Duration;

class InsufficientElementsException extends Exception {
    public InsufficientElementsException(String message) { super(message); }
}

class ElementCount {
    private int count = 0;

    synchronized void increment(int amount) {
        if (amount < 0) throw new IllegalArgumentException();
        count += amount;
    }

    synchronized boolean decrement(int amount) throws InsufficientElementsException {
        if (amount < 0) throw new IllegalArgumentException();
        if (count >= amount) {
            count -= amount;
            return true;
        } else {
            throw new InsufficientElementsException("Insufficient elements to swap");
        }
    }
}

class Container {
    private ElementCount elementCount = new ElementCount();
    private ReentrantLock lock = new ReentrantLock();

    void add(int amount) {
        lock.lock();
        try {
            elementCount.increment(amount);
        } finally {
            lock.unlock();
        }
    }

    boolean swapElementsWith(Container target, int amount, long timeout, TimeUnit unit) throws InsufficientElementsException, InterruptedException {
        if (lock.tryLock(timeout, unit)) {
            try {
                if (target.lock.tryLock(timeout, unit)) {
                    try {
                        if (elementCount.decrement(amount)) {
                            target.add(amount);
                            return true;
                        }
                    } finally {
                        target.lock.unlock();
                    }
                }
            } finally {
                lock.unlock();
            }
        }
        return false;
    }
}

