import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;
import java.time.Duration;

public class DeadlockAvoidance {
    static class InsufficientElementsException extends Exception {}

    private static final Random random = new Random();

    private static long calculateFixedDelay(int retryCount, Duration timeout) {
        return timeout.toMillis() / (retryCount + 1);
    }

    private static long calculateRandomDelay(long fixedDelay) {
        return ThreadLocalRandom.current().nextLong(fixedDelay);
    }

    static class ElementCount {
        private int count;

        public ElementCount(int initialCount) {
            this.count = initialCount;
        }

        public synchronized void add(int amount) {
            if (amount < 0) throw new IllegalArgumentException();
            this.count += amount;
        }

        public synchronized int remove(int amount) throws InsufficientElementsException {
            if (amount < 0) throw new IllegalArgumentException();
            if (this.count < amount) throw new InsufficientElementsException();
            this.count -= amount;
            return amount;
        }
    }

    static class Container<T> {
        private final List<T> elements = new ArrayList<>();
        private final ElementCount count;
        private final ReentrantLock lock = new ReentrantLock();

        public Container(int initialCapacity) {
            this.count = new ElementCount(initialCapacity);
            for (int i = 0; i < initialCapacity; i++) {
                elements.add(null); // Add placeholder elements
            }
        }

        public boolean tryLock(long timeout, TimeUnit unit) {
            try {
                return lock.tryLock(timeout, unit);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException("Interrupted while trying to acquire lock", e);
            }
        }

        public void unlock() {
            lock.unlock();
        }

        // Add methods for adding and removing elements from the container as needed
    }

    static boolean swap(Container<Object> origin, Container<Object> target, int count, long timeout, TimeUnit unit) {
        long fixedDelay = calculateFixedDelay(3, Duration.ofMillis(timeout));
        for (int i = 0; i < 3; i++) {
            if (origin.tryLock(fixedDelay, unit)) {
                try {
                    if (target.tryLock(fixedDelay, unit)) {
                        try {
                            origin.count.remove(count);
                            target.count.add(count);
                            // Perform swap of elements in containers as needed
                            return true;
                        } catch (InsufficientElementsException e) {
                            throw new RuntimeException("Origin container does not have enough elements", e);
                        } finally {
                            target.unlock();
                        }
                    }
                } finally {
                    origin.unlock();
                }
            }
            try {
                Thread.sleep(calculateRandomDelay(fixedDelay));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException("Interrupted while waiting to retry lock acquisition", e);
            }
        }
        return false;
    }

    public static void main(String[] args) {
        // Example usage of the swap method with two containers and thread pool
        Container<Object> container1 = new Container<>(5);
        Container<Object> container2 = new Container<>(3);
        ExecutorService executorService = Executors.newFixedThreadPool(2);
        executorService.submit(() -> {
            try {
                swap(container1, container2, 2, 500, TimeUnit.MILLISECONDS);
            } catch (Exception e) {
                // Handle exception as needed
            }
        });
        executorService.shutdown();
    }
}

