import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;

class NotEnoughWidgetsException extends Exception {
    NotEnoughWidgetsException(String message) { super(message); }
}

class WidgetCount {
    private int count;
    public WidgetCount(int count) { this.count = count; }
    public void add(int amount) { count += amount; }
    public boolean subtract(int amount) throws NotEnoughWidgetsException {
        if (amount > count) throw new NotEnoughWidgetsException("Not enough widgets in bin.");
        count -= amount;
        return true;
    }
}

class Bin {
