import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

enum Constellation { NORTH, SOUTH, EAST, WEST }
enum Resonance { POSITIVE, NEGATIVE }

class Rune {
    private final Constellation constellation;
    private final Resonance resonance;

    public Rune(Constellation constellation, Resonance resonance) {
        this.constellation = constellation;
        this.resonance = resonance;
    }

    // getters and equals/hashCode methods omitted for brevity
}

class Harmony {
    private final Rune rune1, rune2;

    public Harmony(Rune rune1, Rune rune2) {
        this.rune1 = rune1;
        this.rune2 = rune2;
    }

    // getters and equals/hashCode methods omitted for brevity
}

class Grimoire {
    private final List<Harmony> harmonies = new ArrayList<>();

    public void crystallize(Collection<Harmony> harmonies) {
        this.harmonies.addAll(harmonies);
    }

    // getters omitted for brevity
}

class RuneTransmuter implements Callable<Integer> {
    private final Collection<Rune> runes;
    private final Grimoire grimoire;

    public RuneTransmuter(Collection<Rune> runes, Grimoire grimoire) {
        this.runes = runes;
        this.grimoire = grimoire;
    }

    @Override
    public Integer call() throws Exception {
        List<Harmony> harmonies = channelTheGrimoire(runes);
        grimoire.crystallize(harmonies);
        return harmonies.size();
    }

    private List<Harmony> channelTheGrimoire(Collection<Rune> runes) {
        List<Rune> sortedRunes = runes.stream()
                .sorted(Comparator.comparing(Rune::getConstellation).thenComparing(Rune::getResonance))
                .collect(Collectors.toList());

        List<Harmony> harmonies = new ArrayList<>();
        for (int i = 1; i < sortedRunes.size(); i++) {
            Rune prev = sortedRunes.get(i - 1);
            Rune curr = sortedRunes.get(i);

            if (prev.getConstellation() == curr.getConstellation() &&
                    prev.getResonance() != curr.getResonance()) {
                harmonies.add(new Harmony(prev, curr));
            }
        }
        return harmonies;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Grimoire grimoire = new Grimoire();
        Collection<Rune> runes = Arrays.asList(
