import java.util.*;
import java.util.concurrent.*;

enum Constellation { LEO, TAURUS, AQUARIUS, GEMINI }
enum Resonance { POSITIVE, NEGATIVE }

class Rune implements Comparable<Rune> {
    private Constellation constellation;
    private Resonance resonance;

    public Rune(Constellation c, Resonance r) {
        this.constellation = c;
        this.resonance = r;
    }

    public int compareTo(Rune o) {
        return Comparator.comparing((Rune r) -> r.constellation)
                .thenComparingInt(r -> r.resonance == Resonance.POSITIVE ? -1 : 1)
                .compare(this, o);
    }
}

class Harmony {
    private List<Rune> runes;

    public Harmony() {
        this.runes = new ArrayList<>();
    }

    public void addRune(Rune r) {
        runes.add(r);
    }
}

class Grimoire {
    private List<Harmony> harmonies;

    public Grimoire() {
        this.harmonies = new ArrayList<>();
    }

    public void addHarmony(Harmony h) {
        synchronized (this) {
            harmonies.add(h);
        }
    }
}

public class RuneInscription {
    private static int channelTheGrimoire(Collection<Rune> runes, Grimoire grimoire) {
        List<Rune> sortedRunes = new ArrayList<>(runes);
        Collections.sort(sortedRunes);

        ExecutorService executor = Executors.newFixedThreadPool(2);
        try {
            for (int i = 0; i < sortedRunes.size() - 1; i++) {
                Rune r1 = sortedRunes.get(i);
                Rune r2 = sortedRunes.get(i + 1);
                if (r1.constellation == r2.constellation && r1.resonance != r2.resonance) {
                    executor.execute(() -> {
                        Harmony harmony = new Harmony();
                        harmony.addRune(r1);
                        harmony.addRune(r2);
                        grimoire.addHarmony(harmony);
                    });
                }
            }
        } finally {
            executor.shutdown();
        }

        return grimoire.harmonies.size();
    }

    public static void main(String[] args) {
        Collection<Rune> runes = Arrays.asList(
                new Rune(Constellation.LEO, Resonance.POSITIVE),
                new Rune(Constellation.TAURUS, Resonance.NEGATIVE),
                new Rune(Constellation.LEO, Resonance.NEGATIVE),
                new Rune(Constellation.AQUARIUS, Resonance.POSITIVE)
        );
        Grimoire grimoire = new Grimoire();
        int harmoniesFormed = channelTheGrimoire(runes, grimoire);
        System.out.println("Valid harmonies formed: " + harmoniesFormed);
    }
}
