    public int compareTo(Rune other) {
        int cmp = this.constellation.compareTo(other.constellation);
        return cmp == 0 ? this.resonance.compareTo(other.resonance) : cmp;
    }
}

class Harmony {
    Rune firstRune;
    Rune secondRune;

