        List<Rune> runes = Arrays.asList(new Rune[]{ /* initialize with some runes */ });
        channelTheGrimoire(runes);
        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        System.out.println("Number of harmonies: " + grimoire.getNumberOfHarmonies());
    }

    private static void channelTheGrimoire(List<Rune> runes) {
        List<Rune> sortedRunes = runes.stream().sorted().collect(Collectors.toList());

        for (int i = 0; i < sortedRunes.size() - 1; i += 2) {
