            executor.submit(() -> {
                if (sortedRunes.get(finalI).constellation == sortedRunes.get(finalI + 1).constellation &&
                    sortedRunes.get(finalI).resonance != sortedRunes.get(finalI + 1).resonance) {
                    grimoire.addHarmony(new Harmony(sortedRunes.get(finalI), sortedRunes.get(finalI + 1)));
                }
            });
        }
    }
}
