        CelestialCaravanTracker tracker = new CelestialCaravanTracker(new HashMap<>());
        ExecutorService executor = Executors.newFixedThreadPool(5);

        Runnable addBeastsTask = () -> {
            for (int i = 0; i < 1000; i++) {
                tracker.beastHavens.put("Beast_" + i, new Starlight(i, i));
