import java.util.stream.Collectors;

interface Talisman {
    void activate();
}

interface SigilNode<T> {
    T compute();
    List<SigilNode<T>> getChildNodes();
}

class SequentialProcessor<T> {
    private final Function<T, T> computation;
    private final Supplier<List<T>> collectionSupplier;

    public SequentialProcessor(Function<T, T> computation, Supplier<List<T>> collectionSupplier) {
        this.computation = computation;
        this.collectionSupplier = collectionSupplier;
    }

    public List<T> process() {
        return collectionSupplier.get().stream()
                .map(computation)
                .collect(Collectors.toList());
    }
}

class ParallelProcessor<T> {
    private final Function<T, T> computation;
    private final Supplier<List<T>> collectionSupplier;
    private final ExecutorService executor = Executors.newFixedThreadPool(2);

    public ParallelProcessor(Function<T, T> computation, Supplier<List<T>> collectionSupplier) {
        this.computation = computation;
        this.collectionSupplier = collectionSupplier;
    }

    public List<T> process() {
        return collectionSupplier.get().stream()
                .map(item -> executor.submit(() -> computation.apply(item)))
                .map(future -> {
                    try {
                        return future.get();
                    } catch (Exception e) {
                        throw new RuntimeException(e);
                    }
                })
                .collect(Collectors.toList());
    }

    public void shutdown() {
        executor.shutdown();
    }
}

class RecursiveProcessor<T> {
    private final Function<SigilNode<T>, T> computation;
    private final Supplier<SigilNode<T>> rootSupplier;
    private final ExecutorService executor = Executors.newFixedThreadPool(2);

    public RecursiveProcessor(Function<SigilNode<T>, T> computation, Supplier<SigilNode<T>> rootSupplier) {
        this.computation = computation;
        this.rootSupplier = rootSupplier;
    }

    public List<T> processSequentially() {
        return process(this::computeSequentially);
    }

    public List<T> processParallelly() {
        return process(this::computeParallelly);
    }

    private List<T> process(Function<SigilNode<T>, T> nodeComputation) {
        List<T> results = new ArrayList<>();
        processRecursively(rootSupplier.get(), nodeComputation, results);
        return results;
    }

    private void processRecursively(SigilNode<T> node, Function<SigilNode<T>, T> nodeComputation, List<T> results) {
        results.add(nodeComputation.apply(node));
        node.getChildNodes().forEach(child -> processRecursively(child, nodeComputation, results));
    }

    private T computeSequentially(SigilNode<T> node) {
        return computation.apply(node);
    }

    private T computeParallelly(SigilNode<T> node) {
        try {
            Future<T> future = executor.submit(() -> computation.apply(node));
            return future.get();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    public void shutdown() {
        executor.shutdown();
    }
}

