import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

interface Hoard { void transfer(Hoard to, GemAmount amount); }
interface GemAmount { boolean isSufficient(Hoard from); void withdrawFrom(Hoard hoard); void depositTo(Hoard hoard); }
class InsufficientGemsException extends Exception {}

class ConcurrentHoardTransfer {
    public static void main(String[] args) {
        Hoard hoard1 = new SimpleHoard();
        Hoard hoard2 = new SimpleHoard();
        GemAmount transferAmount = new SimpleGemAmount(5);

        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.execute(() -> performTransfer(hoard1, hoard2, transferAmount));
        executor.execute(() -> performTransfer(hoard2, hoard1, transferAmount));

        executor.shutdown();
    }

    private static void performTransfer(Hoard from, Hoard to, GemAmount amount) {
        Lock lowerLock = getLowerLock(from, to);
        Lock higherLock = (lowerLock == fromLock) ? toLock : fromLock;

        try {
            lockOrderedOperation(lowerLock, higherLock, () -> new TransferRitual(from, to, amount).perform());
        } catch (InsufficientGemsException e) {
            System.err.println("Transfer failed due to insufficient gems: " + e.getMessage());
        }
    }

    private static Lock fromLock = new ReentrantLock();
    private static Lock toLock = new ReentrantLock();
    private static Lock tieBreakerLock = new ReentrantLock();

    private static void lockOrderedOperation(Lock first, Lock second, Runnable operation) {
        first.lock();
        try {
            if (first == toLock && first.equals(second)) {
                tieBreakerLock.lock();
            }
            try {
                second.lock();
                try {
                    operation.run();
                } finally {
                    if (!second.equals(first) || !first.equals(toLock)) {
                        second.unlock();
                    }
                }
            } finally {
                if (first == toLock && first.equals(second)) {
                    tieBreakerLock.unlock();
                }
            }
        } finally {
            first.unlock();
        }
    }

    private static Lock getLowerLock(Hoard a, Hoard b) {
        return (System.identityHashCode(a) < System.identityHashCode(b)) ? fromLock : toLock;
    }
}

class SimpleHoard implements Hoard {
    private int gems = 10;
    public void transfer(Hoard to, GemAmount amount) {
        try {
