import java.util.concurrent.*;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

interface VaultNode {
    CrystalAmount getCrystals();
}

interface CrystalAmount {
    boolean withdraw(int amount);
    void deposit(int amount);
    int getCount();
}

class InsufficientCrystalsException extends Exception {}

class TransferRite {
    private final VaultNode from;
    private final VaultNode to;
    private final int amount;

    public TransferRite(VaultNode from, VaultNode to, int amount) {
        this.from = from;
        this.to = to;
        this.amount = amount;
    }

    public void transfer() throws InsufficientCrystalsException {
        Lock lock1 = new ReentrantLock();
        Lock lock2 = new ReentrantLock();
        Lock tieBreaker = new ReentrantLock();

        if (System.identityHashCode(from) < System.identityHashCode(to)) {
            lock1.lock();
            lock2.lock();
        } else if (System.identityHashCode(from) > System.identityHashCode(to)) {
            lock2.lock();
            lock1.lock();
        } else {
            tieBreaker.lock();
            lock1.lock();
            lock2.lock();
            tieBreaker.unlock();
        }

        try {
            if (!from.getCrystals().withdraw(amount)) {
                throw new InsufficientCrystalsException();
            }
            to.getCrystals().deposit(amount);
        } finally {
            lock2.unlock();
            lock1.unlock();
        }
    }
}

