import java.util.concurrent.*;
import java.util.Arrays;

public class AlchemyPotionLoop {
    private final Potion[] loop;
    private int size, putIndex, takeIndex;
    private Semaphore availablePotions, openSlots;

    public AlchemyPotionLoop(int capacity) {
        this.loop = new Potion[capacity];
        Arrays.fill(loop, null);
        this.size = 0;
        this.putIndex = 0;
        this.takeIndex = 0;
        this.availablePotions = new Semaphore(0);
        this.openSlots = new Semaphore(capacity);
    }

    public void put(Potion p) throws InterruptedException {
        openSlots.acquire();
        synchronized (this) {
            loop[putIndex] = p;
            if (++putIndex == loop.length) putIndex = 0;
            size++;
        }
        availablePotions.release();
    }

    public Potion take() throws InterruptedException {
        availablePotions.acquire();
        synchronized (this) {
            Potion p = loop[takeIndex];
            if (++takeIndex == loop.length) takeIndex = 0;
            size--;
            return p;
        }
