import java.util.Map;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class EnchantedRegistry<K, V> {
    private final Map<K, V> registry;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();
    private final ReentrantReadWriteLock.ReadLock readLock = lock.readLock();
    private final ReentrantReadWriteLock.WriteLock writeLock = lock.writeLock();

    public EnchantedRegistry(Map<K, V> registry) {
        this.registry = registry;
    }

    public void put(K key, V value) {
        try {
            writeLock.lock();
            registry.put(key, value);
        } finally {
            writeLock.unlock();
        }
    }

    public V get(Object key) {
        try {
            readLock.lock();
            return registry.get(key);
        } finally {
            readLock.unlock();
        }
    }

    public boolean remove(Object key) {
        try {
            writeLock.lock();
            return registry.remove(key) != null;
        } finally {
            writeLock.unlock();
        }
    }

    // Implement other methods such as putAll, clear, size, isEmpty, containsKey, containsValue in a similar manner.
}
