    public static void transferGold(GoblinPouch from, GoblinPouch to, GoldClump amount) throws InsufficientGoldException {
        Lock firstLock = from.lock;
        Lock secondLock = to.lock;

        if (firstLock != secondLock) {
            boolean acquiredFirstLock = false;
            boolean acquiredSecondLock = false;

            try {
                while (!acquiredFirstLock || !acquiredSecondLock) {
                    if (!acquiredFirstLock) {
                        acquiredFirstLock = firstLock.tryLock();
                    }
                    if (!acquiredSecondLock) {
                        acquiredSecondLock = secondLock.tryLock();
                    }
                }
            } finally {
                if (acquiredFirstLock && !acquiredSecondLock) {
                    firstLock.unlock();
                } else if (!acquiredFirstLock && acquiredSecondLock) {
                    secondLock.unlock();
                }
            }
        }

        from.removeGold(amount);
        to.addGold(amount);
    }
