import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;

public class DeadlockAvoidance {
    static Random rand = new Random();

    public static void main(String[] args) {
        Account source = new Account(new DollarAmount(100));
        Account destination = new Account(new DollarAmount(50));
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable transferTask = () -> {
            try {
                boolean success = transfer(source, destination, new DollarAmount(30), 1000, TimeUnit.MILLISECONDS);
                System.out.println("Transfer successful: " + success);
            } catch (InsufficientFundsException e) {
                System.out.println("Transfer failed: Insufficient funds");
            }
        };

        executor.execute(transferTask);
        executor.shutdown();
    }

    static class DollarAmount {
        private final int value;

        DollarAmount(int value) {
            this.value = value;
        }

        boolean isSufficient(DollarAmount amount) {
            return this.value >= amount.value;
        }
    }

    static class Account {
        private final ReentrantLock lock = new ReentrantLock();
        private DollarAmount balance;

        Account(DollarAmount initialBalance) {
            this.balance = initialBalance;
        }

        void addFunds(DollarAmount amount) {
            balance = new DollarAmount(balance.value + amount.value);
        }

        void subtractFunds(DollarAmount amount) throws InsufficientFundsException {
            if (!balance.isSufficient(amount)) {
                throw new InsufficientFundsException();
            }
            balance = new DollarAmount(balance.value - amount.value);
        }
    }

    static class InsufficientFundsException extends Exception {}

    private static long calculateFixedDelay(long timeout, TimeUnit unit) {
        return unit.toMillis(timeout) / 3; // Example: Divide by 3 for simplicity
    }

    private static int calculateRandomBackoff() {
        return rand.nextInt(3); // Example: Up to 2 seconds random backoff for simplicity
    }

    public static boolean transfer(Account source, Account destination, DollarAmount amount, long timeout, TimeUnit unit) throws InsufficientFundsException {
        long endTime = System.nanoTime() + unit.toNanos(timeout);
        long fixedDelay = calculateFixedDelay(timeout, unit);

        while (true) {
            if (source.lock.tryLock()) {
                try {
                    if (destination.lock.tryLock()) {
                        try {
                            source.subtractFunds(amount);
                            destination.addFunds(amount);
                            return true;
                        } finally {
                            destination.lock.unlock();
                        }
                    }
                } finally {
                    source.lock.unlock();
                }
            }

            if (System.nanoTime() >= endTime) {
                return false;
            }

            try {
                Thread.sleep(fixedDelay + calculateRandomBackoff());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException("Transfer interrupted", e);
            }
        }
    }
}

import java.util.*;
