public class ConcurrentTransfer {
    public static void main(String[] args) {
        Account account1 = new Account(new DollarAmount(500));
        Account account2 = new Account(new DollarAmount(300));
        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.execute(() -> transfer(account1, account2, new DollarAmount(200), 5, TimeUnit.SECONDS));
        executor.execute(() -> transfer(account2, account1, new DollarAmount(400), 5, TimeUnit.SECONDS));
        executor.shutdown();
    }

    public static void transfer(Account source, Account destination, DollarAmount amount, long timeout, TimeUnit unit) {
        Random random = ThreadLocalRandom.current();
        ReentrantLock lock1 = source.getLock();
        ReentrantLock lock2 = destination.getLock();
        boolean acquiredLocks = false;
        long remainingTimeoutNanos = unit.toNanos(timeout);

        while (remainingTimeoutNanos > 0) {
            long startTime = System.nanoTime();
            try {
                if (lock1.tryLock()) {
                    try {
                        if (lock2.tryLock()) {
                            acquiredLocks = true;
                            break;
                        } else {
                            lock1.unlock();
                        }
                    } catch (Exception e) {
                        lock1.unlock();
                        throw e;
                    }
                }
                Thread.sleep(fixedDelayMillis() + randomDelayMillis(random));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            } finally {
                long endTime = System.nanoTime();
                remainingTimeoutNanos -= (endTime - startTime);
            }
        }

        if (acquiredLocks) {
            try {
                source.withdraw(amount);
                destination.deposit(amount);
                System.out.println("Transfer successful");
            } catch (InsufficientFundsException e) {
                System.err.println("Transfer failed: " + e.getMessage());
            } finally {
                lock2.unlock();
                lock1.unlock();
            }
        } else {
            System.err.println("Timeout occurred while attempting to acquire locks");
        }
    }

    private static long fixedDelayMillis() {
        return 50; // 50 milliseconds
    }

    private static long randomDelayMillis(Random random) {
        return random.nextInt(3); // Random delay between 0 to 2 milliseconds
    }
}

