import java.util.concurrent.*;

class BoundedBuffer<E> {
    private final E[] buffer;
    private int size, putIndex, takeIndex;
    private Semaphore availableItems, remainingSpaces;

    public BoundedBuffer(int capacity) {
        this.buffer = (E[]) new Object[capacity];
        this.size = 0;
        this.putIndex = 0;
        this.takeIndex = 0;
        this.availableItems = new Semaphore(0);
        this.remainingSpaces = new Semaphore(capacity);
    }

    public void put(E item) throws InterruptedException {
        remainingSpaces.acquire();
        synchronized (this) {
            buffer[putIndex] = item;
            if (++putIndex == buffer.length) putIndex = 0;
            size++;
        }
        availableItems.release();
    }

    public E take() throws InterruptedException {
        availableItems.acquire();
        synchronized (this) {
            E item = buffer[takeIndex];
            if (++takeIndex == buffer.length) takeIndex = 0;
            size--;
            return item;
        }
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public boolean isFull() {
        return size == buffer.length;
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        BoundedBuffer<Integer> buf = new BoundedBuffer<>(2);
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable producer = () -> {
            for (int i = 0; i < 3; i++) {
                try {
                    buf.put(i);
                    System.out.println("Produced " + i);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        Runnable consumer = () -> {
            for (int i = 0; i < 3; i++) {
                try {
                    int val = buf.take();
                    System.out.println("Consumed " + val);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        executor.execute(producer);
        executor.execute(consumer);

        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
    }
}

