import java.util.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.IntStream;

public class StripedMap<K, V> {
    private static final int N_LOCKS = 16;
    private Node<K, V>[] buckets;
    private Object[] locks;

    public StripedMap(int numBuckets) {
        this.buckets = new Node[numBuckets];
        this.locks = new Object[N_LOCKS];
        Arrays.setAll(locks, i -> new Object());
    }

    public void put(K key, V value) {
        int index = hashIndex(key);
        Node<K, V> node = new Node<>(key, value);

        synchronized (locks[index % N_LOCKS]) {
            if (buckets[index] == null) {
                buckets[index] = node;
            } else {
                Node<K, V> current = buckets[index];
                while (current.next != null && !current.key.equals(key)) {
                    current = current.next;
                }
                if (current.key.equals(key)) {
                    current.value = value; // Overwrite existing key's value
                } else {
                    current.next = node;
                }
            }
        }
    }

    public V get(K key) {
        int index = hashIndex(key);

        synchronized (locks[index % N_LOCKS]) {
            Node<K, V> current = buckets[index];
            while (current != null && !current.key.equals(key)) {
                current = current.next;
            }
            return (current == null) ? null : current.value;
        }
    }

    public void clear() {
        for (int i = 0; i < N_LOCKS; i++) {
            synchronized (locks[i]) {
                IntStream.range(i, buckets.length, N_LOCKS).forEach(j -> buckets[j] = null);
            }
        }
    }

    private int hashIndex(K key) {
        return Math.abs(key.hashCode() % buckets.length);
    }

    private static class Node<K, V> {
        K key;
        V value;
        Node<K, V> next;

        public Node(K key, V value) {
            this.key = key;
            this.value = value;
        }
    }

