class AccountTransferHelper implements Runnable {
    private final Account fromAccount;
    private final Account toAccount;
    private final DollarAmount amount;
    private static final ReentrantLock TIE_BREAKER = new ReentrantLock(true);

    public AccountTransferHelper(Account from, Account to, DollarAmount amount) {
        this.fromAccount = from;
        this.toAccount = to;
        this.amount = amount;
    }

    @Override
    public void run() {
        int fromHash = System.identityHashCode(fromAccount);
        int toHash = System.identityHashCode(toAccount);

        if (fromHash < toHash) {
            synchronized (fromAccount) {
                synchronized (toAccount) {
