                }
            }
        } else if (fromHash > toHash) {
            synchronized (toAccount) {
                synchronized (fromAccount) {
                    performTransfer();
                }
            }
        } else {
            while (true) {
                try {
                    TIE_BREAKER.lock();
                    synchronized (fromAccount) {
                        synchronized (toAccount) {
                            performTransfer();
                            break;
                        }
                    }
                } finally {
                    TIE_BREAKER.unlock();
                }
            }
        }
    }

