public class ArkLoader {

    private static final Comparator<Animal> ANIMAL_COMPARATOR =
            Comparator.comparing(Animal::getSpecies).thenComparing(Animal::getGender);

    public static int loadTheArk(Collection<Animal> candidates) {
        List<Animal> sortedCandidates = new ArrayList<>(candidates);
        sortedCandidates.sort(ANIMAL_COMPARATOR);

        Ark ark = new Ark();
        try (ExecutorService executor = Executors.newFixedThreadPool(2)) {
