import java.util.concurrent.*;
import java.math.BigInteger;

class PrimeProducer implements Runnable {
    private final BlockingQueue<BigInteger> queue;
    private volatile boolean isRunning = true;
    private int primeCountToGenerate;

    public PrimeProducer(BlockingQueue<BigInteger> queue, int primeCountToGenerate) {
        this.queue = queue;
        this.primeCountToGenerate = primeCountToGenerate;
    }

    @Override
    public void run() {
        try {
            BigInteger potentialPrime = BigInteger.ONE;
            while (isRunning && primeCountToGenerate > 0) {
                potentialPrime = potentialPrime.nextProbablePrime();
                if (queue.offer(potentialPrime)) {
                    primeCountToGenerate--;
                } else {
                    Thread.sleep(100); // If queue is full, wait and try again
                }
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            isRunning = false;
        }
    }

    public void stopProducing() {
        this.isRunning = false;
    }
}

class PrimeConsumer implements Runnable {
    private final BlockingQueue<BigInteger> queue;

    public PrimeConsumer(BlockingQueue<BigInteger> queue) {
        this.queue = queue;
    }

    @Override
    public void run() {
        try {
            while (!Thread.currentThread().isInterrupted()) {
                BigInteger prime = queue.poll(100, TimeUnit.MILLISECONDS);
                if (prime != null) {
                    System.out.println("Consumed: " + prime);
                } else {
                    // If no prime is available within the timeout and producer isn't running, stop consuming
                    if (!queue.offer(BigInteger.valueOf(-1), 0, TimeUnit.MILLISECONDS)) {
                        break;
                    }
                }
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        BlockingQueue<BigInteger> queue = new ArrayBlockingQueue<>(10);
        PrimeProducer producer = new PrimeProducer(queue, 2);
        PrimeConsumer consumer = new PrimeConsumer(queue);

        Thread producerThread = new Thread(producer);
        Thread consumerThread = new Thread(consumer);

        producerThread.start();
        consumerThread.start();

        consumerThread.join();

        producer.stopProducing();
        producerThread.join();
    }
}

