public class PrimeProducerConsumer {
    private static final int NUM_PRIMES = 2;
    private static final BlockingQueue<Integer> queue = new ArrayBlockingQueue<>(NUM_PRIMES);

    public static void main(String[] args) throws InterruptedException {
        Thread producer = new PrimeProducer();
        Thread consumer = new Thread(() -> {
            while (true) {
                try {
                    Integer prime = queue.take();
                    if (prime == null) break; // signal to stop
                    System.out.println("Consumed: " + prime);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });

        producer.start();
        consumer.start();

        consumer.join();
        producer.interrupt();
        producer.join();
    }

    private static class PrimeProducer extends Thread {
        @Override
        public void run() {
            int count = 0;
            for (int num = 2; count < NUM_PRIMES && !isInterrupted(); num++) {
                if (isPrime(num)) {
                    try {
                        queue.put(num);
                        count++;
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }
            }
            try {
                queue.put(null); // signal to stop consumer
            } catch (InterruptedException ignored) {}
        }

        private boolean isPrime(int num) {
            if (num <= 1) return false;
            for (int i = 2; i * i <= num; i++) {
                if (num % i == 0) return false;
            }
            return true;
        }
    }
