import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

interface Element {
    void process();
}

interface Node extends Element {
    List<Node> getChildren();
}

class SequentialProcessor<T extends Element> {
    public void process(List<T> elements) {
        for (T element : elements) {
            element.process();
        }
    }

    public <R> R processRecursive(Node root, BiFunction<R, R, R> combiner) {
        List<CompletableFuture<R>> futures = new ArrayList<>();
        for (Node child : root.getChildren()) {
            CompletableFuture<R> future = CompletableFuture.supplyAsync(() -> processRecursive(child, combiner));
            futures.add(future);
        }
        R result = null;
        try {
            for (CompletableFuture<R> future : futures) {
                if (result == null) {
                    result = future.get();
                } else {
                    result = combiner.apply(result, future.get());
                }
            }
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
        return root.process(), result;
    }
}

class ParallelProcessor<T extends Element> {
    private final ExecutorService executor = Executors.newFixedThreadPool(2);

    public void process(List<T> elements) {
        List<CompletableFuture<?>> futures = new ArrayList<>();
        for (T element : elements) {
            CompletableFuture<?> future = CompletableFuture.runAsync(() -> element.process(), executor);
            futures.add(future);
        }
        try {
            CompletableFuture<Void> allFutures = CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]));
            allFutures.get();
        } catch (Exception e) {
            throw new RuntimeException(e);
        } finally {
            executor.shutdown();
        }
    }

    public <R> R processRecursive(Node root, BiFunction<R, R, R> combiner) {
        CompletableFuture<R> result = new CompletableFuture<>();
        List<CompletableFuture<R>> futures = new ArrayList<>();
        for (Node child : root.getChildren()) {
            CompletableFuture<R> future = CompletableFuture.supplyAsync(() -> processRecursive(child, combiner), executor);
            futures.add(future);
        }
        R finalResult = null;
        try {
            for (CompletableFuture<R> future : futures) {
                if (finalResult == null) {
                    finalResult = future.get();
                } else {
                    finalResult = combiner.apply(finalResult, future.get());
                }
            }
        } catch (Exception e) {
            throw new RuntimeException(e);
        } finally {
            executor.shutdown();
        }
        return root.process(), finalResult;
    }
