import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

interface Element<T> { T process(); }

interface Node<T> extends Element<T> {
    List<Node<T>> getChildren();
}

class SequentialProcessor<T> implements Element<List<T>> {
    private final List<? extends Element<T>> elements;

    SequentialProcessor(List<? extends Element<T>> elements) {
        this.elements = elements;
    }

    @Override
    public List<T> process() {
        List<T> result = new ArrayList<>();
        for (Element<T> element : elements) {
            result.add(element.process());
        }
        return result;
    }
}

class ParallelProcessor<T> implements Element<List<T>> {
    private final List<? extends Element<T>> elements;

    ParallelProcessor(List<? extends Element<T>> elements) {
        this.elements = elements;
    }

    @Override
    public List<T> process() {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        List<Future<T>> futures = new ArrayList<>();

        for (Element<T> element : elements) {
            futures.add(executor.submit(element::process));
        }

        List<T> result = new ArrayList<>();
        for (Future<T> future : futures) {
            try {
                result.add(future.get());
            } catch (InterruptedException | ExecutionException e) {
                Thread.currentThread().interrupt();
            }
        }

        executor.shutdown();
        return result;
    }
}

