import java.util.stream.Collectors;

interface Element { void process(); }
interface Node<T> extends Element { List<Node<T>> getChildren(); T computeResult(); }

class SequentialProcessor<T> {
    <E extends Element> void process(List<E> elements) {
        for (Element element : elements) {
            element.process();
        }
    }

    <N extends Node<T>> List<T> recursiveProcess(Node<T> node) {
        List<T> results = new ArrayList<>();
        results.add(node.computeResult());
        for (Node<T> child : node.getChildren()) {
            results.addAll(recursiveProcess(child));
        }
        return results;
    }
}

class ParallelProcessor<T> {
    private ExecutorService executor = Executors.newFixedThreadPool(2);

    <E extends Element> void process(List<E> elements) throws InterruptedException {
        List<CompletableFuture<Void>> futures = new ArrayList<>();
        for (Element element : elements) {
            CompletableFuture<Void> future = CompletableFuture.runAsync(() -> element.process(), executor);
            futures.add(future);
        }
        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).get();
    }

    <N extends Node<T>> List<T> recursiveProcess(Node<T> node) throws InterruptedException {
        List<CompletableFuture<List<T>>> futures = new ArrayList<>();
        for (Node<T> child : node.getChildren()) {
            CompletableFuture<List<T>> future = CompletableFuture.supplyAsync(() -> recursiveProcess(child), executor);
            futures.add(future);
        }
        List<List<T>> results = new ArrayList<>(futures.stream()
                .map(CompletableFuture::join)
                .collect(Collectors.toList()));
        results.add(0, Collections.singletonList(node.computeResult()));
        return results.stream().flatMap(Collection::stream).collect(Collectors.toList());
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        List<Element> elements = Arrays.asList(() -> System.out.println("Processed sequentially"), () -> System.out.println("Processed concurrently"));
        SequentialProcessor<Integer> sequentialProcessor = new SequentialProcessor<>();
        ParallelProcessor<Integer> parallelProcessor = new ParallelProcessor<>();
        sequentialProcessor.process(elements);
        parallelProcessor.process(elements);
    }
}

