import java.util.*;
import java.util.concurrent.locks.*;

class ReadWriteMap<K, V> {
    private final Map<K, V> map;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public ReadWriteMap(Map<K, V> map) {
        this.map = map;
    }

    public V get(Object key) {
        lock.readLock().lock();
        try {
            return map.get(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public void put(K key, V value) {
        lock.writeLock().lock();
        try {
            map.put(key, value);
        } finally {
            lock.writeLock().unlock();
        }
    }

    // Implement the remaining methods similarly...
}

public class Main {
    public static void main(String[] args) {
        ReadWriteMap<Integer, String> map = new ReadWriteMap<>(new HashMap<>());

        // Using a fixed thread pool of size 3 (main thread + 2 worker threads)
        ExecutorService executor = java.util.concurrent.Executors.newFixedThreadPool(3);

        Runnable writer = () -> {
            for (int i = 0; i < 2; i++) {
                map.put(i, "Value" + i);
                System.out.println("Writer wrote: Value" + i);
            }
        };

        Runnable reader = () -> {
            for (int i = 0; i < 2; i++) {
                String value = map.get(i);
                System.out.println("Reader read: " + value);
            }
        };

        executor.execute(writer);
        executor.execute(reader);
        executor.execute(reader);

        executor.shutdown();
    }
}

